//! Port of `compact.cpp`.

#[allow(unused_imports)]
use crate::prelude::*;

use crate::range::Range;

/*------------------------------------------------------------------------*/

// Compacting removes holes generated by inactive variables (fixed,
// eliminated, substituted or pure) by mapping active variables indices down
// to a contiguous interval of indices.

/*------------------------------------------------------------------------*/

impl Internal {
    pub fn compacting(&mut self) -> bool {
        if self.level != 0 {
            return false;
        }
        if self.opts.compact == 0 {
            return false;
        }
        if self.stats.conflicts < self.lim.compact {
            return false;
        }
        let inactive = self.max_var - self.active_count();
        debug_assert!(inactive >= 0);
        if inactive == 0 {
            return false;
        }
        if inactive < self.opts.compactmin {
            return false;
        }
        inactive as f64 >= (1e-3 * self.opts.compactlim as f64) * self.max_var as f64
    }
}

/*------------------------------------------------------------------------*/

struct Mapper {
    /// Old 'max_var' (C++ 'internal->max_var' while mapping).
    max_var: i32,
    /// New 'max_var' after compacting.
    new_max_var: i32,
    /// Old variable index to new literal map.
    table: Vec<i32>,
    /// First fixed variable index.
    first_fixed: i32,
    /// Mapped literal of first fixed variable.
    map_first_fixed: i32,
    /// Value of first fixed variable.
    first_fixed_val: i8,
    new_vsize: usize,
}

impl Mapper {
    /*----------------------------------------------------------------------*/
    // We produce a compacting garbage collector like map of old 'src' to
    // new 'dst' variables.  Inactive variables are just skipped except for
    // fixed ones which will be mapped to the first fixed variable (in the
    // appropriate phase).  This avoids to handle the case 'fixed value'
    // separately as it is done in Lingeling, where fixed variables are
    // mapped to the internal variable '1'.
    //
    fn new(internal: &Internal) -> Mapper {
        let mut m = Mapper {
            max_var: internal.max_var,
            new_max_var: 0,
            table: vec![0; internal.max_var as usize + 1],
            first_fixed: 0,
            map_first_fixed: 0,
            first_fixed_val: 0,
            new_vsize: 0,
        };

        debug_assert!(internal.level == 0);

        for src in internal.vars() {
            let f = internal.flags(src);
            if f.active() {
                m.new_max_var += 1;
                m.table[src as usize] = m.new_max_var;
            } else if f.fixed() && m.first_fixed == 0 {
                m.first_fixed = src;
                m.new_max_var += 1;
                m.map_first_fixed = m.new_max_var;
                m.table[src as usize] = m.map_first_fixed;
            }
        }

        m.first_fixed_val = if m.first_fixed != 0 { internal.val(m.first_fixed) } else { 0 };
        m.new_vsize = m.new_max_var as usize + 1;
        m
    }

    /*----------------------------------------------------------------------*/
    // Map old variable indices.  A result of zero means not mapped.
    //
    #[inline]
    fn map_idx(&self, src: i32) -> i32 {
        debug_assert!(0 < src);
        debug_assert!(src <= self.max_var);
        let res = self.table[src as usize];
        debug_assert!(res <= self.new_max_var);
        res
    }

    /*----------------------------------------------------------------------*/
    // The 'map_idx' above is just a look-up into the 'table'.  Here we have
    // to care about signedness of 'src', and in addition that fixed
    // variables have all to be mapped to the first fixed variable
    // 'first_fixed'.  ('vals' is the (not yet mapped) 'internal->vals'.)
    //
    #[inline]
    fn map_lit(&self, vals: *const i8, src: i32) -> i32 {
        let mut res = self.map_idx(src.abs());
        if res == 0 {
            // SAFETY: 'src' is within '[-max_var,max_var]'.
            let tmp = unsafe { *vals.offset(src as isize) };
            if tmp != 0 {
                debug_assert!(self.first_fixed != 0);
                res = self.map_first_fixed;
                if tmp != self.first_fixed_val {
                    res = -res;
                }
            }
        } else if src < 0 {
            res = -res;
        }
        debug_assert!(res.abs() <= self.new_max_var);
        res
    }

    /*----------------------------------------------------------------------*/
    // Map positive variable indices in vector.  (C++ copies 'v[src]' to
    // 'v[dst]'.  Since 'dst <= src' and the map is monotone, swapping gives
    // the same result for the remaining '[0,new_vsize)' entries.)
    //
    fn map_vector<T: Default>(&self, v: &mut Vec<T>) {
        for src in Range::new(self.max_var) {
            let dst = self.map_idx(src);
            if dst == 0 {
                continue;
            }
            debug_assert!(0 < dst);
            debug_assert!(dst <= src);
            v.swap(dst as usize, src as usize);
        }
        v.resize_with(self.new_vsize, T::default);
        shrink_vector(v);
    }

    /*----------------------------------------------------------------------*/
    // Map positive and negative variable indices in two-sided vector.
    //
    fn map2_vector<T: Default>(&self, v: &mut Vec<T>) {
        for src in Range::new(self.max_var) {
            let dst = self.map_idx(src);
            if dst == 0 {
                continue;
            }
            debug_assert!(0 < dst);
            debug_assert!(dst <= src);
            v.swap(2 * dst as usize, 2 * src as usize);
            v.swap(2 * dst as usize + 1, 2 * src as usize + 1);
        }
        v.resize_with(2 * self.new_vsize, T::default);
        shrink_vector(v);
    }

    /*----------------------------------------------------------------------*/
    // Map a vector of literals, flush inactive literals, then resize and
    // shrink it to fit the new size after flushing.
    //
    fn map_flush_and_shrink_lits(&self, v: &mut Vec<i32>) {
        let end = v.len();
        let mut j = 0;
        for i in 0..end {
            let src = v[i];
            let mut dst = self.map_idx(src.abs());
            debug_assert!(dst.abs() <= src.abs());
            if dst == 0 {
                continue;
            }
            if src < 0 {
                dst = -dst;
            }
            v[j] = dst;
            j += 1;
        }
        v.truncate(j);
        shrink_vector(v);
    }
}

/*------------------------------------------------------------------------*/

impl Internal {
    pub fn compact(&mut self) {
        start!(self, compact);

        debug_assert!(self.active_count() < self.max_var);

        self.stats.compacts += 1;

        debug_assert!(self.level == 0);
        debug_assert!(!self.unsat);
        debug_assert!(self.conflict.is_null());
        debug_assert!(self.clause.is_empty());
        debug_assert!(self.levels.is_empty());
        debug_assert!(self.analyzed.is_empty());
        debug_assert!(self.minimized.is_empty());
        debug_assert!(self.control.len() == 1);
        debug_assert!(self.propagated == self.trail.len());

        self.garbage_collection();

        let mapper = Mapper::new(self);

        if mapper.first_fixed != 0 {
            log!(self, "found first fixed {}", sign(mapper.first_fixed_val as i32) * mapper.first_fixed);
        } else {
            log!(self, "no variable fixed");
        }

        let external = self.ext_unbound();

        if !self.assumptions.is_empty() {
            debug_assert!(!external.assumptions.is_empty());
            log!(self, "temporarily reset internal assumptions");
            self.reset_assumptions();
        }

        let is_constraint = !self.constraint.is_empty();
        if is_constraint {
            debug_assert!(!external.constraint.is_empty());
            log!(self, "temporarily reset internal constraint");
            self.reset_constraint();
        }

        /*====================================================================*/
        // In this first part we only map stuff without reallocation /
        // shrinking.
        /*====================================================================*/

        // Flush the external indices.  This has to occur before we map
        // 'vals'.  Also fixes external units.
        //
        for eidx in external.vars() {
            let src = external.e2i[eidx as usize];
            if src == 0 {
                continue;
            }
            if self.lrat || self.frat {
                debug_assert!(eidx > 0);
                debug_assert!(external.ext_units.len() >= 2 * eidx as usize + 1);
                let id1 = external.ext_units[2 * eidx as usize];
                let id2 = external.ext_units[2 * eidx as usize + 1];
                debug_assert!(id1 == 0 || id2 == 0);
                if id1 == 0 && id2 == 0 {
                    let new_id1 = *self.unit_clauses(2 * src);
                    let new_id2 = *self.unit_clauses(2 * src + 1);
                    external.ext_units[2 * eidx as usize] = new_id1;
                    external.ext_units[2 * eidx as usize + 1] = new_id2;
                }
            }
            let dst = mapper.map_lit(self.vals, src);
            log!(
                self,
                "compact {} maps external {} to internal {} from internal {}",
                self.stats.compacts,
                eidx,
                dst,
                src
            );
            external.e2i[eidx as usize] = dst;
        }

        // Delete garbage units. Needs to occur before resizing unit_clauses
        //
        if self.lrat || self.frat {
            for src in self.vars() {
                let dst = mapper.map_idx(src);
                debug_assert!(dst <= src);
                let tmp = self.val(src);
                if dst == 0 && tmp == 0 {
                    *self.unit_clauses(2 * src) = 0;
                    *self.unit_clauses(2 * src + 1) = 0;
                    continue;
                }
                if tmp == 0 || src == mapper.first_fixed {
                    debug_assert!(0 < dst);
                    if dst == src {
                        continue;
                    }
                    debug_assert!(*self.unit_clauses(2 * dst) == 0 && *self.unit_clauses(2 * dst + 1) == 0);
                    *self.unit_clauses(2 * dst) = *self.unit_clauses(2 * src);
                    *self.unit_clauses(2 * dst + 1) = *self.unit_clauses(2 * src + 1);
                    *self.unit_clauses(2 * src) = 0;
                    *self.unit_clauses(2 * src + 1) = 0;
                    continue;
                }
                let mut id = *self.unit_clauses(2 * src);
                #[allow(unused_variables, unused_mut)]
                let mut lit = src;
                if id == 0 {
                    id = *self.unit_clauses(2 * src + 1);
                    lit = -lit;
                }
                *self.unit_clauses(2 * src) = 0;
                *self.unit_clauses(2 * src + 1) = 0;
                debug_assert!(id != 0);
                let _ = (id, lit);
            }
            self.unit_clauses_idx.resize(2 * mapper.new_vsize, 0);
            shrink_vector(&mut self.unit_clauses_idx);
        }
        // Map the literals in all clauses.
        //
        for k in 0..self.clauses.len() {
            let c = self.clauses[k];
            debug_assert!(!c.garbage());
            for i in 0..c.size() as usize {
                let src = c.lit(i);
                debug_assert!(self.val(src) == 0);
                let dst = mapper.map_lit(self.vals, src);
                debug_assert!(dst != 0 || c.garbage());
                c.set_lit(i, dst);
            }
        }

        // Map the blocking literals in all watches.
        //
        if !self.wtab.is_empty() {
            let vals = self.vals;
            for lit in self.lits() {
                for w in self.watches_mut(lit).iter_mut() {
                    w.blit = mapper.map_lit(vals, w.blit);
                }
            }
        }

        // We first flush inactive variables and map the links in the queue.
        // This has to be done before we map the actual links data structure
        // 'links'.
        {
            let mut prev = 0;
            let mut mapped_prev = 0;
            let mut next;
            let mut idx = self.queue.first;
            while idx != 0 {
                next = self.links[idx as usize].next;
                if idx == mapper.first_fixed {
                    idx = next;
                    continue;
                }
                let dst = mapper.map_idx(idx);
                if dst == 0 {
                    idx = next;
                    continue;
                }
                debug_assert!(self.active(idx));
                if prev != 0 {
                    self.links[prev as usize].next = dst;
                } else {
                    self.queue.first = dst;
                }
                self.links[idx as usize].prev = mapped_prev;
                mapped_prev = dst;
                prev = idx;
                idx = next;
            }
            if prev != 0 {
                self.links[prev as usize].next = 0;
            } else {
                self.queue.first = 0;
            }
            self.queue.last = mapped_prev;
            self.queue.unassigned = mapped_prev;
        }

        /*====================================================================*/
        // In the second part we map, flush and shrink arrays.
        /*====================================================================*/

        debug_assert!(self.trail.len() == self.num_assigned);
        mapper.map_flush_and_shrink_lits(&mut self.trail);
        self.propagated = self.trail.len();
        self.num_assigned = self.trail.len();
        if mapper.first_fixed != 0 {
            debug_assert!(self.trail.len() == 1);
            self.var_mut(mapper.first_fixed).trail = 0; // before mapping 'vtab'
        } else {
            debug_assert!(self.trail.is_empty());
        }

        if !self.probes.is_empty() {
            mapper.map_flush_and_shrink_lits(&mut self.probes);
        }

        if !self.sweep_schedule.is_empty() {
            mapper.map_flush_and_shrink_lits(&mut self.sweep_schedule);
        }

        /*====================================================================*/
        // In the third part we map stuff and also reallocate memory.
        /*====================================================================*/

        // Now we continue in reverse order of allocated bytes, e.g., see
        // 'Internal::enlarge' which reallocates in order of allocated bytes.

        mapper.map_vector(&mut self.ftab);
        mapper.map_vector(&mut self.parents);
        mapper.map_vector(&mut self.marks);
        mapper.map_vector(&mut self.phases.saved);
        mapper.map_vector(&mut self.phases.forced);
        mapper.map_vector(&mut self.phases.target);
        mapper.map_vector(&mut self.phases.best);
        mapper.map_vector(&mut self.phases.prev);

        // Special code for 'frozentab'.
        //
        for src in self.vars() {
            let dst = mapper.map_lit(self.vals, src).abs();
            if dst == 0 {
                continue;
            }
            if src == dst {
                continue;
            }
            debug_assert!(dst < src);
            if src as usize >= self.frozentab.len() {
                break;
            }
            if dst as usize >= self.frozentab.len() {
                break;
            }
            let add = self.frozentab[src as usize];
            self.frozentab[dst as usize] = self.frozentab[dst as usize].wrapping_add(add);
            self.frozentab[src as usize] = 0;
        }
        let new_len = self.frozentab.len().min(mapper.new_vsize);
        self.frozentab.resize(new_len, 0);
        shrink_vector(&mut self.frozentab);

        // Special code for 'relevanttab'.
        //
        if !self.external.is_null() {
            for src in self.vars() {
                let dst = mapper.map_lit(self.vals, src).abs();
                if dst == 0 {
                    continue;
                }
                if src == dst {
                    continue;
                }
                debug_assert!(dst < src);

                let add = self.relevanttab[src as usize];
                self.relevanttab[dst as usize] = self.relevanttab[dst as usize].wrapping_add(add);
                self.relevanttab[src as usize] = 0;
            }
            self.relevanttab.resize(mapper.new_vsize, 0);
            shrink_vector(&mut self.relevanttab);
        }

        /*--------------------------------------------------------------------*/

        if !external.assumptions.is_empty() {
            for k in 0..external.assumptions.len() {
                let elit = external.assumptions[k];
                debug_assert!(elit != 0);
                debug_assert!(elit != i32::MIN);
                let eidx = elit.abs();
                debug_assert!(eidx <= external.max_var);
                let mut ilit = external.e2i[eidx as usize];
                debug_assert!(ilit != 0); // Because we froze all!!!
                if elit < 0 {
                    ilit = -ilit;
                }
                self.assume(ilit);
            }

            phase!(
                self,
                "compact",
                self.stats.compacts,
                "reassumed {} external assumptions",
                external.assumptions.len()
            );
        }

        // Special case for 'val' as for 'val' we trade branch less code for
        // memory and always allocated an [-maxvar,...,maxvar] array.
        {
            let new_vsize = mapper.new_vsize;
            let mut new_storage: Vec<i8> = vec![0; 2 * new_vsize];
            // SAFETY: 'new_vsize' is within the new allocation.
            let new_vals = unsafe { new_storage.as_mut_ptr().add(new_vsize) };
            // SAFETY: mapped indices are within '[-new_max_var,new_max_var]'
            // of the new and 'src' within '[-max_var,max_var]' of the old
            // allocation.
            unsafe {
                for src in self.vars() {
                    *new_vals.offset(-(mapper.map_idx(src) as isize)) = *self.vals.offset(-(src as isize));
                }
                for src in self.vars() {
                    *new_vals.offset(mapper.map_idx(src) as isize) = *self.vals.offset(src as isize);
                }
                *new_vals = 0;
            }
            self.vals_storage = new_storage;
            self.vals = new_vals;
            self.vsize = new_vsize;
        }

        // 'constrain' uses 'val', so this code has to be after remapping
        // that
        if is_constraint {
            debug_assert!(self.level == 0);
            debug_assert!(*external.constraint.last().unwrap() == 0);
            for k in 0..external.constraint.len() {
                let elit = external.constraint[k];
                debug_assert!(elit != i32::MIN);
                let eidx = elit.abs();
                debug_assert!(eidx <= external.max_var);
                let mut ilit = external.e2i[eidx as usize];
                debug_assert!((ilit == 0) == (elit == 0));
                if elit < 0 {
                    ilit = -ilit;
                }
                log!(self, "re adding lit external {} internal {} to constraint", elit, ilit);
                self.constrain(ilit);
            }
            phase!(
                self,
                "compact",
                self.stats.compacts,
                "added {} external literals to constraint",
                external.constraint.len() - 1
            );
        }

        mapper.map_vector(&mut self.i2e);
        mapper.map2_vector(&mut self.ptab);
        mapper.map_vector(&mut self.btab);
        mapper.map_vector(&mut self.gtab);
        mapper.map_vector(&mut self.links);
        mapper.map_vector(&mut self.vtab);
        if !self.ntab.is_empty() {
            mapper.map2_vector(&mut self.ntab);
        }
        if !self.wtab.is_empty() {
            mapper.map2_vector(&mut self.wtab);
        }
        if !self.otab.is_empty() {
            mapper.map2_vector(&mut self.otab);
        }
        if !self.rtab.is_empty() {
            mapper.map2_vector(&mut self.rtab);
        }
        if !self.big.is_empty() {
            mapper.map2_vector(&mut self.big);
        }

        /*====================================================================*/
        // In the fourth part we map the binary heap for scores.
        /*====================================================================*/

        // The simplest way to map a binary heap is to get all elements from
        // the heap and reinsert them.  This could be slightly improved in
        // terms of speed if we add a 'flush (int * map)' function to 'Heap',
        // but that is pretty complicated and would require that the 'Heap'
        // knows that mapped elements with 'zero' destination should be
        // flushed.

        let mut saved: Vec<i32> = Vec::new();
        debug_assert!(saved.is_empty());
        if !self.scores.empty() {
            while !self.scores.empty() {
                let src = self.scores.front() as i32;
                self.scores.pop_front();
                let dst = mapper.map_idx(src);
                if dst == 0 {
                    continue;
                }
                if src == mapper.first_fixed {
                    continue;
                }
                saved.push(dst);
            }
            self.scores.erase();
        }
        mapper.map_vector(&mut self.stab);
        if !saved.is_empty() {
            for &idx in saved.iter() {
                self.scores.push_back(idx as u32);
            }
            self.scores.shrink();
        }

        /*--------------------------------------------------------------------*/

        phase!(
            self,
            "compact",
            self.stats.compacts,
            "reducing internal variables from {} to {}",
            self.max_var,
            mapper.new_max_var
        );

        /*--------------------------------------------------------------------*/

        // Need to adjust the target and best assigned counters too.

        let mut new_target_assigned: usize = 0;
        let mut new_best_assigned: usize = 0;

        for idx in Range::new(mapper.new_max_var) {
            if self.phases.target[idx as usize] != 0 {
                new_target_assigned += 1;
            }
            if self.phases.best[idx as usize] != 0 {
                new_best_assigned += 1;
            }
        }

        log!(self, "reset target assigned from {} to {}", self.target_assigned, new_target_assigned);
        log!(self, "reset best assigned from {} to {}", self.best_assigned, new_best_assigned);

        self.target_assigned = new_target_assigned;
        self.best_assigned = new_best_assigned;
        self.no_conflict_until = 0;
        self.notified = 0;

        init_ema!(self, averages.current.trail.fast, self.opts.ematrailfast);
        init_ema!(self, averages.current.trail.slow, self.opts.ematrailslow);

        /*--------------------------------------------------------------------*/

        self.max_var = mapper.new_max_var;

        self.stats.unused = 0;
        self.stats.now.fixed = if mapper.first_fixed != 0 { 1 } else { 0 };
        self.stats.inactive = self.stats.now.fixed;
        self.stats.now.pure = 0;
        self.stats.now.eliminated = 0;
        self.stats.now.substituted = 0;

        self.check_var_stats();

        let delta: i64 = self.opts.compactint as i64 * (self.stats.compacts + 1);
        self.lim.compact = self.stats.conflicts + delta;

        phase!(
            self,
            "compact",
            self.stats.compacts,
            "new compact limit {} after {} conflicts",
            self.lim.compact,
            delta
        );

        stop!(self, compact);
    }
}
